<div class="page-heading"><div><div class="eyebrow">Ruang pemohon</div><h1>Daftar UTTP saya</h1><p>Simpan beberapa alat beserta alamat dan koordinat masing-masing. Data ini dapat ditarik saat membuat permohonan.</p></div><?php if ($this->metro->can($current_user->id,'self.uttp.create')): ?><button type="button" class="button primary" data-modal-open="uttp-modal-0">+ Tambah UTTP</button><?php endif; ?></div>

<section class="registry-list"><?php if ($items): foreach ($items as $item): ?><article class="registry-item"><div class="section-heading compact"><div><strong><?= e($item->uttp_name) ?> · <?= e($item->brand) ?></strong><small><?= e($item->owner_name) ?><?= $item->serial_number?' · No. seri '.e($item->serial_number):'' ?></small><small><?= e($item->service_address) ?></small><small><?= $item->latitude!==NULL && $item->longitude!==NULL?e($item->latitude.', '.$item->longitude):'Koordinat belum diisi' ?></small></div><span class="badge <?= $item->is_active?'success':'danger' ?>"><?= $item->is_active?'Aktif':'Nonaktif' ?></span></div><?php if ($item->latitude!==NULL && $item->longitude!==NULL): ?><div class="geo-display geo-detail-map" data-points="<?= e(json_encode(array(array('lat'=>(float)$item->latitude,'lng'=>(float)$item->longitude,'title'=>$item->uttp_name,'detail'=>$item->service_address,'kind'=>'UTTP')),JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)) ?>"></div><?php endif; ?><p class="muted small"><?php if (in_array((int)$item->uttp_type_id,array(10,48),TRUE)): ?>Media <?= e($item->media?:'—') ?> · Nozzle <?= e($item->nozzle_no?:'—') ?> · Dispenser <?= e($item->dispenser_no?:'—') ?><?php else: ?>Daya baca <?= e($item->readability?:'—') ?><?php endif; ?></p><div class="registry-actions"><a class="button outline small-button" href="<?= site_url('uttp/riwayat/'.$item->id) ?>">Riwayat</a><?php if ($this->metro->can($current_user->id,'self.uttp.update')): ?><button type="button" class="button outline small-button" data-modal-open="uttp-modal-<?= (int)$item->id ?>">Edit</button><?php endif; ?><?php if ($this->metro->can($current_user->id,'self.uttp.status')): ?><form method="post" action="<?= site_url('uttp/status/'.$item->id) ?>"><?= form_hidden($this->security->get_csrf_token_name(),$this->security->get_csrf_hash()) ?><button class="button outline small-button" type="submit"><?= $item->is_active?'Nonaktifkan':'Aktifkan' ?></button></form><?php endif; ?><?php if ($this->metro->can($current_user->id,'self.uttp.delete')): ?><form method="post" action="<?= site_url('uttp/hapus/'.$item->id) ?>" onsubmit="return confirm('Hapus UTTP yang belum digunakan dalam permohonan?')"><?= form_hidden($this->security->get_csrf_token_name(),$this->security->get_csrf_hash()) ?><button class="button outline small-button" type="submit">Hapus</button></form><?php endif; ?></div></article><?php endforeach; else: ?><div class="card empty"><h3>Belum ada UTTP tersimpan</h3><p>Tambahkan alat pertama untuk mengisi permohonan lebih cepat.</p></div><?php endif; ?></section>
